function GetVehicleBrandLogo(value)
    local vehicleLabel = GetVehicleLabel(value)
    if not vehicleLabel then goto continue end

    for _, brand in pairs(brands or {}) do
        for k, vehicle in pairs(brand.vehicles) do
            if vehicle == vehicleLabel then
                local atlas = brand_atlas[brand.icons.image[1]]

                if atlas then
