function GetVehiclePreviewImage(value)
    local modelHash = GetVehicleModelHash(value)
    if not modelHash then return end

    for imageName, vehicles in pairs(atlas2) do
        for hash, data in pairs(vehicles) do
            if hash == modelHash then
                return {
                    location = imageName,
                    x = data.x,
                    y = data.y,
                }
            end
        end
    end

    return nil
end